<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {api,type Configuration} from './api';
const props=defineProps<{config:Configuration;admin:boolean;dirty:boolean}>();
const state=ref<{enabled:boolean;tankIds:string[];changedAtUtc:string|null;warning:string}|null>(null),selected=ref<string[]>([]),confirmed=ref(false),token=ref(''),busy=ref(false),error=ref(''),message=ref('');
async function load(){state.value=await api('/api/integration/access');selected.value=[...(state.value?.tankIds||[])];confirmed.value=false}
async function save(enabled:boolean){if(busy.value)return;busy.value=true;error.value='';token.value='';try{if(props.dirty)throw Error('请先保存或重新载入待保存配置');const result=await api<{token:string|null;message:string}>('/api/integration/access','POST',{configurationRevision:props.config.revision,enabled,tankIds:enabled?selected.value:[],confirmed:confirmed.value});token.value=result.token||'';message.value=result.message;await load()}catch(e){error.value=String(e)}finally{busy.value=false}}
onMounted(()=>{if(props.admin)void load().catch(e=>error.value=String(e))});
</script>
<template><section class="panel panel-body"><h2>对外只读接口</h2><p class="help">供指定接入方读取当前数据，采用独立令牌，只开放下列已选择储罐。新增储罐需重新授权；此接口不支持仪表操作、配置写入或历史下载。</p><p v-if="!admin" class="notice">请管理员设置对外只读接口。</p><template v-else><p>状态：{{state?.enabled?'已启用':'已关闭'}} <small v-if="state?.changedAtUtc">最近设置 {{new Date(state.changedAtUtc).toLocaleString('zh-CN')}}</small></p><p v-if="state?.warning" class="notice">{{state.warning}}</p><p v-if="error" role="alert" class="error-message">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p><p>地址：<code>/api/external/v1/current</code><br>请求头：<code>Authorization: Bearer &lt;独立只读令牌&gt;</code></p><p class="help">默认仅监听本机；其他电脑接入需另行配置监听地址、网络与HTTPS。最多每分钟120次，建议每2秒读取一次。各值同时提供单位、数据质量和时间；无效值为空，冻结液面和上次任务平均值单独标识。</p><fieldset><legend>允许读取的储罐</legend><div class="group-choices"><label v-for="t in config.tanks" :key="t.id" class="checkbox"><input v-model="selected" type="checkbox" :value="t.id">{{t.code}}{{t.hidden?' · 隐藏':''}}</label></div><p v-if="!config.tanks.length" class="help">请先配置储罐。</p></fieldset><label class="checkbox"><input v-model="confirmed" type="checkbox">确认本次范围，并使旧令牌失效</label><div class="inline-actions"><button class="button primary" :disabled="busy||dirty||!confirmed||!selected.length" @click="save(true)">{{state?.enabled?'重新生成令牌并更新范围':'启用并生成令牌'}}</button><button class="button" :disabled="busy||dirty||!confirmed||!state?.enabled" @click="save(false)">关闭并吊销令牌</button></div><label v-if="token" class="config-field">本次独立只读令牌（仅显示一次）<textarea readonly rows="3" :value="token" aria-label="本次独立只读令牌"></textarea></label></template></section></template>
